import{lessons,heartKeys,heartPart,partNames,flowSteps,cardiacPhases,thoraxQuestions}from'./thorax-data.js';
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class ThoraxCourse{
 constructor(api){this.api=api;this.active=false;this.step=0;this.phase=0;this.flow=0;this.quiz=-1;this.score=0;this.answered=false;this.timer=null;this.ticket=0;this.records=[];}
 async open(){this.active=true;document.body.classList.add('thorax-active');$('#thoraxPanel').hidden=false;$('#thoraxPanel').setAttribute('tabindex','-1');$('#thoraxPanel').focus();this.quiz=-1;this.step=0;await this.show();}
 close(){this.ticket++;this.stop();this.active=false;this.quiz=-1;$('#thoraxPanel').hidden=true;document.body.classList.remove('thorax-active');this.api.exit();}
 stop(){clearInterval(this.timer);this.timer=null;const b=$('#coursePlay');if(b)b.textContent='▶ Oynat';this.api.motion(false);}
 async show(){const ticket=++this.ticket;this.stop();this.phase=0;this.flow=0;const l=lessons[this.step];$('#thoraxPanel').innerHTML='<p>Göğüs yapıları yükleniyor…</p><button id="courseClose">Derse son ver</button>';$('#courseClose').onclick=()=>this.close();try{this.records=await this.api.view(this.quiz>=0?heartKeys:l.keys,{inside:this.quiz>=0||l.inside,highlight:this.quiz>=0?[]:l.highlight});if(ticket!==this.ticket||!this.active)return;this.render();}catch(e){if(ticket!==this.ticket)return;$('#thoraxPanel').innerHTML='<h2>Ders yüklenemedi</h2><p>Model dosyaları açılamadı.</p><button id="courseRetry">Yeniden dene</button><button id="courseClose">Derse son ver</button>';$('#courseRetry').onclick=()=>this.show();$('#courseClose').onclick=()=>this.close();}}
 render(){const l=lessons[this.step],groups=[...new Set(this.records.map(heartPart).filter(Boolean))],missing=(this.quiz>=0?heartKeys:l.keys).filter(k=>!groups.includes(k));$('#thoraxPanel').innerHTML='<div class="course-top"><span>KALP VE GÖĞÜS ATÖLYESİ</span><button id="courseClose" aria-label="Dersi kapat">×</button></div><nav class="course-tabs">'+lessons.map((x,i)=>'<button data-lesson="'+i+'" aria-current="'+(this.step===i&&this.quiz<0?'step':'false')+'">'+(i+1)+'</button>').join('')+'<button id="courseQuiz">Sına</button></nav><p class="course-progress">'+(this.quiz>=0?'Model üzerinde alıştırma':(this.step+1)+' / '+lessons.length)+'</p><h2>'+esc(this.quiz>=0?'Öğrendiklerini bul':l.title)+'</h2><div id="courseBody"></div><p id="coursePicked" role="status"></p><details class="course-scope"><summary>Kaynak ve model kapsamı</summary><p>'+groups.length+' yapı grubu bu referansta bulunuyor.'+(missing.length?' Eksik: '+missing.map(k=>partNames[k]).join(', ')+'.':'')+'</p><p>Erkek modelinde AV kapak yaprakçıkları eksiktir; kadın modelinde kapaklar ayrı bütün yapılar olarak bulunur. İnce damar ağı ve tam lif mimarisi eklenmemiştir.</p><a href="'+l.source+'" target="_blank" rel="noreferrer">Ders kaynağı ↗</a><p>Kaynak temelli eğitim taslağı. Anatomi uzmanı incelemesi bekliyor.</p></details><div class="course-bottom"><button id="coursePrev">← Önceki</button><button id="courseNext">Sonraki →</button></div>';
 $('#courseClose').onclick=()=>this.close();document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{this.quiz=-1;this.step=Number(b.dataset.lesson);this.show();});$('#courseQuiz').onclick=()=>{this.quiz=0;this.score=0;this.answered=false;this.show();};$('#coursePrev').disabled=this.step===0&&this.quiz<0;$('#coursePrev').onclick=()=>{this.quiz=-1;this.step=Math.max(0,this.step-1);this.show();};$('#courseNext').onclick=()=>{if(this.quiz>=0){if(!this.answered){this.feedback('Önce soruyu yanıtla veya cevabı göster.');return;}this.quiz++;this.answered=false;this.renderQuiz();}else if(this.step===lessons.length-1){this.quiz=0;this.score=0;this.answered=false;this.show();}else{this.step++;this.show();}};
 if(this.quiz>=0){this.renderQuiz();return;}$('#courseBody').innerHTML='<p>'+esc(l.text)+'</p><div class="course-task">'+esc(l.task)+'</div>'+(l.flow||l.cycle?'<div id="courseDynamics"></div>':'')+(l.reference?this.referenceHTML():'')+(l.breathing?'<button id="courseBreath">▶ Solunumu göster</button><p>Diyafram geometrisi yalnızca erkek referansında mevcuttur.</p>':'')+'<div class="course-structures">'+groups.map(k=>'<button data-part="'+k+'">'+partNames[k]+'</button>').join('')+'</div>';
 document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{this.api.highlight([b.dataset.part],true);this.feedback(partNames[b.dataset.part]);});if(l.flow||l.cycle)this.renderDynamics();if(l.breathing)$('#courseBreath').onclick=e=>{const on=e.target.dataset.play!=='on';e.target.dataset.play=on?'on':'';e.target.textContent=on?'Ⅱ Duraklat':'▶ Solunumu göster';this.api.motion(on);};if(l.reference)this.wireReference();}
 feedback(text){$('#coursePicked').textContent=text;}
 onPick(r){if(!this.active)return false;const key=heartPart(r);if(this.quiz>=0){this.answer(key);return true;}this.feedback((partNames[key]||'Seçili yapı')+' · '+r.name);this.api.highlight([key],false);return true;}
 renderQuiz(){const q=thoraxQuestions[this.quiz];if(!q){$('#courseBody').innerHTML='<h3>'+this.score+' / '+thoraxQuestions.length+' ilk denemede doğru</h3><p>Yanlış seçtiğin yapıların konumunu ders adımlarında yeniden inceleyebilirsin.</p><button id="courseRestart">Alıştırmayı tekrarla</button>';$('#courseNext').disabled=true;$('#courseRestart').onclick=()=>{this.quiz=0;this.score=0;this.answered=false;this.renderQuiz();};return;}$('#courseNext').disabled=false;this.api.highlight([],false);$('#coursePicked').textContent='';$('#courseBody').innerHTML='<p>Soru '+(this.quiz+1)+' / '+thoraxQuestions.length+'</p><h3>'+q.q+'</h3><p>Modelde dokun veya aşağıdan bir yapı seç.</p><div class="course-structures">'+['ra','rv','la','lv','mitral','tricuspid'].filter(k=>this.records.some(r=>heartPart(r)===k)).map(k=>'<button data-answer-part="'+k+'">'+partNames[k]+'</button>').join('')+'</div><button id="courseReveal">Cevabı göster</button>';document.querySelectorAll('[data-answer-part]').forEach(b=>b.onclick=()=>this.answer(b.dataset.answerPart));$('#courseReveal').onclick=()=>this.answer(null);}
 answer(key){const q=thoraxQuestions[this.quiz];if(!q||this.answered)return;this.answered=true;const correct=key===q.target;if(correct)this.score++;this.api.highlight([q.target],true);this.feedback((correct?'Doğru. ':key?'Bu yapı değil. Doğru yapı vurgulandı. ':'Doğru yapı vurgulandı. ')+q.why);document.querySelectorAll('[data-answer-part]').forEach(b=>b.disabled=true);}
 renderDynamics(){const isFlow=lessons[this.step].flow,p=cardiacPhases[this.phase],av=p.av?35:0,sl=p.sl?35:0;$('#courseDynamics').innerHTML='<div class="cycle-map"><svg viewBox="0 0 300 220" role="img" aria-label="Şematik sağ ve sol kalp, kapak açıklıkları"><defs><marker id="flowArrow" markerWidth="7" markerHeight="7" refX="5" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#78c7b0"/></marker></defs><rect x="25" y="35" width="105" height="58" rx="22" fill="#375b86"/><rect x="170" y="35" width="105" height="58" rx="22" fill="#8e4650"/><rect x="25" y="120" width="105" height="70" rx="24" fill="#375b86"/><rect x="170" y="120" width="105" height="70" rx="24" fill="#8e4650"/><g fill="white" font-size="11" text-anchor="middle"><text x="77" y="67">Sağ kulakçık</text><text x="222" y="67">Sol kulakçık</text><text x="77" y="157">Sağ karıncık</text><text x="222" y="157">Sol karıncık</text></g><g stroke="#f0d080" stroke-width="4"><path d="M50 106 L77 106" transform="rotate('+av+' 50 106)"/><path d="M104 106 L77 106" transform="rotate('+(-av)+' 104 106)"/><path d="M195 106 L222 106" transform="rotate('+av+' 195 106)"/><path d="M249 106 L222 106" transform="rotate('+(-av)+' 249 106)"/></g><path d="M128 172 Q150 200 150 20 M273 172 Q293 200 293 20" stroke="#78c7b0" fill="none" marker-end="url(#flowArrow)" stroke-width="2"/><g stroke="#f0d080" stroke-width="4"><path d="M143 100 L157 100" transform="rotate('+sl+' 143 100)"/><path d="M284 100 L298 100" transform="rotate('+sl+' 284 100)"/></g></svg><small>İşlev şeması · anatomik konum veya ölçek çizimi değildir</small></div><h3>'+(isFlow?flowSteps[this.flow][1]:p.title)+'</h3><p>'+(isFlow?'Adım '+(this.flow+1)+' / '+flowSteps.length:p.text)+'</p>'+(!isFlow?'<div class="valve-status">AV kapaklar: <b>'+(p.av?'Açık':'Kapalı')+'</b><br>Aort / pulmoner: <b>'+(p.sl?'Açık':'Kapalı')+'</b></div>':'')+'<div class="course-bottom"><button id="phaseBack">←</button><button id="coursePlay">'+(this.timer?'Ⅱ Duraklat':'▶ Oynat')+'</button><button id="phaseNext">→</button></div>';
 if(isFlow){$('#courseDynamics .cycle-map').outerHTML='<div class=flow-route>'+flowSteps.map(([key,label],i)=>'<span class="'+(i===this.flow?'current':'')+'">'+esc(label)+(i<flowSteps.length-1?' →':'')+'</span>').join(' ')+'</div>';}
 const advance=n=>{if(isFlow){this.flow=(this.flow+n+flowSteps.length)%flowSteps.length;this.api.highlight([flowSteps[this.flow][0]],false);}else{this.phase=(this.phase+n+cardiacPhases.length)%cardiacPhases.length;this.api.highlight(cardiacPhases[this.phase].highlight,false);this.api.phase(cardiacPhases[this.phase].fraction);}this.renderDynamics();};$('#phaseBack').onclick=()=>{this.stop();advance(-1);};$('#phaseNext').onclick=()=>{this.stop();advance(1);};$('#coursePlay').onclick=()=>{if(this.timer){this.stop();this.renderDynamics();}else{this.timer=setInterval(()=>{if(!document.hidden)advance(1);},1400);this.renderDynamics();}};if(isFlow)this.api.highlight([flowSteps[this.flow][0]],false);else{this.api.highlight(p.highlight,false);this.api.phase(p.fraction);}}
 referenceHTML(){return '<button id=courseVolume>160 kesitli hacmi üç yönde incele ↗</button><label for="referenceSex">Kesit örneği</label><select id="referenceSex"><option value="male">Visible Human · Erkek · a_vm1450</option><option value="female">Visible Human · Kadın · avf1588a</option></select><label for="referenceZoom">Yakınlaştırma</label><input id="referenceZoom" type="range" min="100" max="300" value="100"><div class="reference-scroll"><img id="referencePhoto" src="./reference/a_vm1450.png" alt="NLM gerçek anatomik göğüs kesiti"></div><p>Tek örnek kesit; sürekli BT/MR dizisi değildir. Aynı referans seçilse bile 3B modelle konum eşleştirmesi yapılmamıştır.</p><a href="https://www.nlm.nih.gov/research/visible/full_color_png.html" target="_blank" rel="noreferrer">NLM · Özgün kesitler ↗</a>';}
 wireReference(){$('#courseVolume').onclick=()=>document.dispatchEvent(new Event('open-anatomy-volume'));$('#referenceSex').value=this.api.sex();const update=()=>{$('#referencePhoto').src='./reference/'+($('#referenceSex').value==='female'?'avf1588a.png':'a_vm1450.png');$('#referencePhoto').style.width=$('#referenceZoom').value+'%';};$('#referenceSex').onchange=update;$('#referenceZoom').oninput=update;$('#referencePhoto').onerror=()=>this.feedback('Kesit fotoğrafı yüklenemedi. Kaynak bağlantısını kullanabilirsin.');update();}
}
